package com.tascode.codebridge.language.subset;
import com.tascode.codebridge.diagnostic.Diagnostic;
import com.tascode.codebridge.diagnostic.Severity;
import com.tascode.codebridge.ir.*;
import com.tascode.codebridge.language.Language;
import com.tascode.codebridge.language.LanguageGenerator;
import java.util.List;
public final class SubsetFunctionGenerator implements LanguageGenerator {
 private final boolean cppStyle;
 private final Language targetLanguage;
 public SubsetFunctionGenerator(){this(Language.C);}
 public SubsetFunctionGenerator(Language targetLanguage){this.targetLanguage=java.util.Objects.requireNonNull(targetLanguage);this.cppStyle=targetLanguage==Language.CPP;}
 public Language language(){return targetLanguage;}
 public GenerationResult generate(IrNode root){if(!(root instanceof Program p))return new GenerationResult(null,List.of(Diagnostic.withoutLocation(Severity.ERROR,targetLanguage==Language.CPP?"CB-GEN-CPP-ROOT":"CB-GEN-C-ROOT","C generation requires a program node.")));StringBuilder b=new StringBuilder();try{if(targetLanguage==Language.C||targetLanguage==Language.CPP){java.util.List<String> includes=new java.util.ArrayList<>(p.includes());if(hasCstdio(p)&&!includes.contains("stdio.h"))includes.add("stdio.h");if(cppStyle&&hasCout(p)&&!includes.contains("iostream"))includes.add("iostream");if(cppStyle&&hasString(p)&&!includes.contains("string"))includes.add("string");for(String include:includes)b.append("#include <").append(include).append(">\n");if(!includes.isEmpty()&&!p.functions().isEmpty())b.append('\n');}for(FunctionDeclaration f:p.functions()){if(b.length()>0&&b.charAt(b.length()-1)!='\n')b.append('\n');function(b,f);}return new GenerationResult(b.toString(),List.of());}catch(UnsupportedOperationException e){return new GenerationResult(null,List.of(Diagnostic.withoutLocation(Severity.ERROR,targetLanguage==Language.CPP?"CB-GEN-CPP-UNSUPPORTED":"CB-GEN-C-UNSUPPORTED",e.getMessage())));}}
 private boolean hasString(Program p){return p.functions().stream().anyMatch(f->(f.returnType().equals("string")||f.returnType().equals("String"))||f.parameters().stream().anyMatch(x->(x.type().equals("string")||x.type().equals("String")))||hasString(f.body()));} private boolean hasString(Statement s){if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasString);if(s instanceof VariableDeclaration v)return (v.type().equals("string")||v.type().equals("String"))||v.initializer().map(this::hasString).orElse(false);if(s instanceof ArrayDeclaration a)return a.elementType().equals("string")||a.elementType().equals("String");if(s instanceof ReturnStatement r)return r.value().map(this::hasString).orElse(false);if(s instanceof ExpressionStatement e)return hasString(e.expression());if(s instanceof IfStatement i)return hasString(i.thenBranch())||i.elseBranch().map(this::hasString).orElse(false);if(s instanceof WhileStatement w)return hasString(w.body());if(s instanceof DoWhileStatement d)return hasString(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasString).orElse(false)||hasString(f.body());return false;} private boolean hasString(Expression e){if(e instanceof LiteralExpression l)return l.value() instanceof String;if(e instanceof BinaryExpression b)return hasString(b.left())||hasString(b.right());if(e instanceof CallExpression c)return c.arguments().stream().anyMatch(this::hasString);return false;} private boolean hasCstdio(Program p){return p.functions().stream().anyMatch(f->hasCstdio(f.body()));}
 private boolean hasCstdio(Statement s){if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasCstdio);if(s instanceof VariableDeclaration v)return v.initializer().map(this::hasCstdio).orElse(false);if(s instanceof ReturnStatement r)return r.value().map(this::hasCstdio).orElse(false);if(s instanceof ExpressionStatement e)return hasCstdio(e.expression());if(s instanceof IfStatement i)return hasCstdio(i.condition())||hasCstdio(i.thenBranch())||i.elseBranch().map(this::hasCstdio).orElse(false);if(s instanceof WhileStatement w)return hasCstdio(w.condition())||hasCstdio(w.body());if(s instanceof DoWhileStatement d)return hasCstdio(d.condition())||hasCstdio(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasCstdio).orElse(false)||f.condition().map(this::hasCstdio).orElse(false)||f.update().map(this::hasCstdio).orElse(false)||hasCstdio(f.body());if(s instanceof ArrayDeclaration a)return hasCstdio(a.size());return false;}
 private boolean hasCstdio(Expression e){if(e instanceof CallExpression c)return java.util.Set.of("printf","puts","scanf").contains(c.callee())||c.arguments().stream().anyMatch(this::hasCstdio);if(e instanceof BinaryExpression b)return hasCstdio(b.left())||hasCstdio(b.right());if(e instanceof UnaryExpression u)return hasCstdio(u.operand());if(e instanceof AssignmentExpression a)return hasCstdio(a.target())||hasCstdio(a.value());if(e instanceof ArrayAccessExpression a)return hasCstdio(a.array())||hasCstdio(a.index());return false;} private boolean hasCout(Program p){return p.functions().stream().anyMatch(f->hasCout(f.body()));} private boolean hasCout(Statement s){if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasCout);if(s instanceof ExpressionStatement e)return hasCout(e.expression());if(s instanceof IfStatement i)return hasCout(i.thenBranch())||i.elseBranch().map(this::hasCout).orElse(false);if(s instanceof WhileStatement w)return hasCout(w.body());if(s instanceof DoWhileStatement d)return hasCout(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasCout).orElse(false)||hasCout(f.body());return false;} private boolean hasCout(Expression e){return e instanceof CallExpression c&&(c.callee().equals("__codebridge_cout")||c.arguments().stream().anyMatch(this::hasCout));}
 private String typeName(String type){if(cppStyle&&(type.equals("string")||type.equals("String")))return "std::string";if(cppStyle&&type.equals("_Bool"))return "bool";if(!cppStyle&&type.equals("bool"))return "_Bool";return type;}
 private void function(StringBuilder b,FunctionDeclaration f){b.append(typeName(f.returnType())).append(' ').append(f.name()).append('(');if(f.parameters().isEmpty()){if(!cppStyle)b.append("void");}else for(int i=0;i<f.parameters().size();i++){if(i>0)b.append(", ");Parameter p=f.parameters().get(i);b.append(typeName(p.type())).append(' ').append(p.name());}b.append(") ");block(b,f.body(),0);b.append('\n');}
 private void block(StringBuilder b,BlockStatement x,int d){b.append("{\n");for(Statement s:x.statements()){b.append("    ".repeat(d+1));statement(b,s,d+1);b.append('\n');}b.append("    ".repeat(d)).append('}');}
 private void statement(StringBuilder b,Statement s,int d){if(s instanceof BlockStatement x)block(b,x,d);else if(s instanceof ArrayDeclaration x){b.append(typeName(x.elementType())).append(' ').append(x.name()).append('[');expression(b,x.size());b.append("];");}else if(s instanceof VariableDeclaration x){b.append(typeName(x.type())).append(' ').append(x.name());x.initializer().ifPresent(e->{b.append(" = ");expression(b,e);});b.append(';');}else if(s instanceof ExpressionStatement x){expression(b,x.expression());b.append(';');}else if(s instanceof ReturnStatement x){b.append("return");x.value().ifPresent(e->{b.append(' ');expression(b,e);});b.append(';');}else if(s instanceof BreakStatement)b.append("break;");else if(s instanceof ContinueStatement)b.append("continue;");else if(s instanceof ForStatement x){b.append("for (");x.initializer().ifPresent(init->{if(init instanceof VariableDeclaration v){b.append(typeName(v.type())).append(' ').append(v.name());v.initializer().ifPresent(value->{b.append(" = ");expression(b,value);});}else if(init instanceof ExpressionStatement e)expression(b,e.expression());else throw new UnsupportedOperationException("Unsupported for initializer");});b.append("; ");x.condition().ifPresent(e->expression(b,e));b.append("; ");x.update().ifPresent(e->expression(b,e));b.append(") ");statement(b,x.body(),d);}else if(s instanceof IfStatement x){b.append("if (");expression(b,x.condition());b.append(") ");statement(b,x.thenBranch(),d);x.elseBranch().ifPresent(branch->{b.append(" else ");statement(b,branch,d);});}else if(s instanceof DoWhileStatement x){b.append("do ");statement(b,x.body(),d);b.append(" while (");expression(b,x.condition());b.append(");");}else if(s instanceof WhileStatement x){b.append("while (");expression(b,x.condition());b.append(") ");statement(b,x.body(),d);}else throw new UnsupportedOperationException("Unsupported C statement node: "+s.getClass().getSimpleName());}
 private String quoteString(String value){StringBuilder out=new StringBuilder("\"");for(char c:value.toCharArray()){switch(c){case '\\'->out.append("\\\\");case '"'->out.append("\\\"");case '\n'->out.append("\\n");case '\r'->out.append("\\r");case '\t'->out.append("\\t");case '\b'->out.append("\\b");case '\f'->out.append("\\f");default->out.append(c);}}return out.append('"').toString();} private String characterLiteral(char value){return switch(value){case '\n'->"'\\n'";case '\r'->"'\\r'";case '\t'->"'\\t'";case '\b'->"'\\b'";case '\f'->"'\\f'";case '\\'->"'\\\\'";case '\''->"'\\''";case '"'->"'\"'";default->"'"+value+"'";};}
private void expression(StringBuilder b,Expression e){if(e instanceof LiteralExpression x){if(x.value() instanceof String s)b.append(quoteString(s));else if(x.value() instanceof Boolean v)b.append(v?"1":"0");else if(x.value() instanceof Character c)b.append(characterLiteral(c));else b.append(x.value());}else if(e instanceof NameExpression x)b.append(x.name());else if(e instanceof BinaryExpression x){b.append('(');expression(b,x.left());b.append(' ').append(x.operator()).append(' ');expression(b,x.right());b.append(')');}else if(e instanceof ArrayAccessExpression x){expression(b,x.array());b.append('[');expression(b,x.index());b.append(']');}else if(e instanceof AssignmentExpression x){b.append('(');expression(b,x.target());b.append(" = ");expression(b,x.value());b.append(')');}else if(e instanceof UpdateExpression x){b.append('(');if(x.prefix())b.append(x.operator());b.append(x.target().name());if(!x.prefix())b.append(x.operator());b.append(')');}else if(e instanceof UnaryExpression x){b.append('(').append(x.operator());expression(b,x.operand());b.append(')');}else if(e instanceof CallExpression x){if(x.callee().equals("__codebridge_cout")){b.append("std::cout");for(Expression item:x.arguments()){b.append(" << ");if(item instanceof CallExpression endl&&endl.callee().equals("__codebridge_endl"))b.append("std::endl");else expression(b,item);}return;}b.append(x.callee()).append('(');for(int i=0;i<x.arguments().size();i++){if(i>0){b.append(", ");if(x.callee().equals("scanf")&&i==1)b.append((char)38);}expression(b,x.arguments().get(i));}b.append(')');}else throw new UnsupportedOperationException("Unsupported C expression node: "+e.getClass().getSimpleName());}
}



